def desenhar_vitoria(screen):
    # Exibe a mensagem somente quando houver um vencedor.
    if vencedor_partida is None or transicao_promocao is not None:
        return
    tempo = pygame.time.get_ticks() - tempo_vitoria

    # Escurecimento progressivo antes da comemoração.
    camada = pygame.Surface((LARGURA, ALTURA), pygame.SRCALPHA)
    camada.fill((0, 0, 0, int(170 * min(1, tempo / 650))))
    screen.blit(camada, (0, 0))
    if tempo < 650:
        return
    # Confetes dourados e verdes, durante quatro segundos.
    t = (tempo - 650) / 1000
    if t < 4:
        for i in range(64):
            x = int((i * 97 + 20 * math.sin(t * 3 + i)) % LARGURA)
            y = int((i * 53 % 350) - 350 + t * (130 + i % 5 * 25))
            cor = [(212, 175, 55), (245, 235, 215), (70, 170, 95)][i % 3]
            pygame.draw.rect(screen, cor, (x, y, 5, 9))

    # Centraliza a caixa de mensagem.
    largura_caixa = 570
    altura_caixa = 230
    x = (LARGURA - largura_caixa) // 2
    y = (ALTURA - altura_caixa) // 2
    caixa = pygame.Rect(x, y, largura_caixa, altura_caixa)

    # Fundo bege e borda dourada.
    pygame.draw.rect(screen, (245, 235, 215), caixa, border_radius=15)
    pygame.draw.rect(screen, (212, 175, 55), caixa, 5, border_radius=15)

    # Define as fontes e cria os textos.
    fonte_titulo = pygame.font.SysFont("arial", 40, bold=True)
    fonte_mensagem = pygame.font.SysFont("arial", 28, bold=True)
    fonte_motivo = pygame.font.SysFont("arial", 20, bold=True)

    texto1 = fonte_motivo.render(resultado["motivo"].upper() + "!", True, (120, 90, 30))
    texto2 = fonte_titulo.render("PARABÉNS!", True, (40, 120, 60))
    texto3 = fonte_mensagem.render(f"AS PEÇAS {vencedor_partida}", True, (40, 40, 40))
    texto4 = fonte_mensagem.render("GANHARAM O JOGO!", True, (40, 40, 40))

    # Exibe os textos centralizados.
    screen.blit(texto1, texto1.get_rect(center=(LARGURA // 2, y + 30)))
    screen.blit(texto2, texto2.get_rect(center=(LARGURA // 2, y + 85)))
    screen.blit(texto3, texto3.get_rect(center=(LARGURA // 2, y + 145)))
    screen.blit(texto4, texto4.get_rect(center=(LARGURA // 2, y + 185)))


