def salvar_resultado():
    global aviso_gravacao
    caminho = PASTA_HISTORICO / (id_partida + ".txt")
    temporario = caminho.with_suffix(".tmp")
    try:
        PASTA_HISTORICO.mkdir(exist_ok=True)
        # Troca o arquivo somente depois que a escrita completa termina.
        temporario.write_text(json.dumps(resultado, ensure_ascii=False) + "\n",
                              encoding="utf-8")
        temporario.replace(caminho)
        aviso_gravacao = ""
    except OSError as erro:
        aviso_gravacao = "Falha ao salvar o resultado."
        print(f"{aviso_gravacao} {erro}")


def ler_historico():
    registros = []
    ignorados = 0
    try:
        caminhos = list(PASTA_HISTORICO.glob("*.txt"))
    except OSError:
        return registros, "Falha ao ler a pasta de histórico."
    for caminho in caminhos:
        try:
            partida = json.loads(caminho.read_text(encoding="utf-8"))
            if not isinstance(partida, dict):
                raise ValueError("Registro inválido")
            data = datetime.fromisoformat(partida["data"])
            if data.tzinfo is None:
                raise ValueError("Data sem fuso horário")
            for chave in ("brancas", "pretas", "motivo"):
                if not isinstance(partida[chave], str) or not partida[chave].strip():
                    raise ValueError("Texto ausente")
            if partida["vencedor"] not in ("b", "p", ""):
                raise ValueError("Resultado inválido")
            registros.append(partida)
        except (OSError, ValueError, KeyError, TypeError):
            ignorados += 1
    registros.sort(key=lambda partida: datetime.fromisoformat(partida["data"]),
                   reverse=True)
    aviso = f"Arquivos inválidos ou ilegíveis: {ignorados}." if ignorados else ""
    return registros, aviso


def calcular_ranking(registros):
    # Cada linha guarda nome, pontos, vitórias, empates e derrotas.
    jogadores_ranking = {}
    for partida in registros:
        for cor, campo in (("b", "brancas"), ("p", "pretas")):
            nome = partida[campo]
            dados = jogadores_ranking.setdefault(nome.casefold(), [nome, 0, 0, 0, 0])
            if partida["vencedor"] == cor:
                dados[1] += 3
                dados[2] += 1
            elif partida["vencedor"] == "":
                dados[1] += 1
                dados[3] += 1
            else:
                dados[4] += 1
    return sorted(jogadores_ranking.values(),
                  key=lambda linha: (-linha[1], -linha[2], linha[0].casefold()))


def validar_nomes(nomes):
    limpos = [" ".join(nome.split()) for nome in nomes]
    if any(not any(letra.isalpha() for letra in nome) for nome in limpos):
        return limpos, "Digite um nome com pelo menos uma letra em cada campo."
    if limpos[0].casefold() == limpos[1].casefold():
        return limpos, "Use nomes diferentes para identificar os jogadores."
    return limpos, ""


def escrever(texto, tipografia, cor, x, y, largura=None, centro=False):
    if largura is not None and tipografia.size(texto)[0] > largura:
        while texto and tipografia.size(texto + "…")[0] > largura:
            texto = texto[:-1]
        texto += "…"
    imagem = tipografia.render(texto, True, cor)
    if centro:
        x -= imagem.get_width() // 2
    screen.blit(imagem, (x, y))


