def acoes_partida_disponiveis():
    """Permite acordos e desistência entre lances completos."""
    return (not jogo_encerrado and not animando and promocao_pendente is None
            and transicao_promocao is None)


def confirmar_abandono():
    """Aplica o resultado da desistência para a posição atual."""
    adversario = cor_adversaria(turno_atual)
    material = {"b": [], "p": []}
    for linha in tabuleiro_estado:
        for peca in linha:
            if peca != "--" and peca[1] != "R":
                material[peca[0]].append(peca[1])

    pecas_adversarias = material[adversario]
    if (not pecas_adversarias
            or (not material[turno_atual] and pecas_adversarias in (["B"], ["C"]))):
        encerrar_partida("", "Mate impossível após desistência")
    else:
        encerrar_partida(adversario, "Desistência")


def tratar_comando_partida(evento):
    global cursor_linha, cursor_coluna
    global peca_selecionada, origem_selecionada, movimentos_disponiveis
    global oferta_empate, confirmar_desistencia
    clique = evento.type == pygame.MOUSEBUTTONDOWN and evento.button == 1
    if confirmar_desistencia:
        if clique and ACEITAR_EMPATE.collidepoint(evento.pos):
            confirmar_abandono()
        elif ((clique and DESISTIR.collidepoint(evento.pos))
              or (evento.type == pygame.KEYDOWN and evento.key == pygame.K_ESCAPE)):
            confirmar_desistencia = False
        return
    if jogo_encerrado or animando or transicao_promocao is not None:
        return
    if clique and acoes_partida_disponiveis():
        if DESISTIR.collidepoint(evento.pos):
            confirmar_desistencia = True
            return
        if OFERECER_EMPATE.collidepoint(evento.pos) and oferta_empate is None:
            oferta_empate = turno_atual
            return
        if (ACEITAR_EMPATE.collidepoint(evento.pos)
                and oferta_empate == cor_adversaria(turno_atual)):
            encerrar_partida("", "Empate por acordo")
            return
    if evento.type == pygame.KEYDOWN:
        tecla = evento.key
        if promocao_pendente is not None:
            tipos = {pygame.K_d: "D", pygame.K_t: "T", pygame.K_b: "B", pygame.K_c: "C"}
            if tecla in tipos:
                promover_peao(tipos[tecla])
        elif tecla == pygame.K_UP:
            cursor_linha = max(0, cursor_linha - 1)
        elif tecla == pygame.K_DOWN:
            cursor_linha = min(7, cursor_linha + 1)
        elif tecla == pygame.K_LEFT:
            cursor_coluna = max(0, cursor_coluna - 1)
        elif tecla == pygame.K_RIGHT:
            cursor_coluna = min(7, cursor_coluna + 1)
        elif tecla in (pygame.K_RETURN, pygame.K_KP_ENTER):
            selecionar_casa(cursor_linha, cursor_coluna)
        elif tecla == pygame.K_ESCAPE:
            peca_selecionada, origem_selecionada, movimentos_disponiveis = None, None, []
    elif evento.type == pygame.MOUSEBUTTONDOWN and evento.button == 1:
        x, y = evento.pos
        if y < ALTURA and promocao_pendente is None:
            cursor_linha, cursor_coluna = y // TAMANHO_QUADRADO, x // TAMANHO_QUADRADO
            selecionar_casa(cursor_linha, cursor_coluna)


def executar():
    carregar_imagens()
    tela = "menu"
    nomes = ["", ""]
    foco, cursor = 0, 0
    aviso = ""
    confirmar_saida = False
    pagina, paginas = 0, 1
    linhas = []
    pygame.key.start_text_input()

    while True:
        dt = clock.tick(60)
        for evento in pygame.event.get():
            if evento.type == pygame.QUIT:
                pygame.quit()
                return
            clique = evento.type == pygame.MOUSEBUTTONDOWN and evento.button == 1
            tecla = evento.key if evento.type == pygame.KEYDOWN else None

            if tela == "menu":
                iniciar = tecla in (pygame.K_RETURN, pygame.K_KP_ENTER)
                destino = ""
                if clique:
                    for indice, campo in enumerate(CAMPOS):
                        if campo.collidepoint(evento.pos):
                            foco, cursor = indice, len(nomes[indice])
                    iniciar = INICIAR.collidepoint(evento.pos)
                    if RANKING.collidepoint(evento.pos):
                        destino = "ranking"
                    elif HISTORICO.collidepoint(evento.pos):
                        destino = "historico"

                if iniciar:
                    limpos, aviso = validar_nomes(nomes)
                    if not aviso:
                        iniciar_partida(limpos)
                        confirmar_saida = False
                        tela = "partida"
                        pygame.key.stop_text_input()
                elif destino:
                    linhas, aviso = ler_historico()
                    if destino == "ranking":
                        linhas = calcular_ranking(linhas)
                    pagina = 0
                    paginas = max(1, (len(linhas) + TAMANHO_PAGINA - 1) // TAMANHO_PAGINA)
                    tela = destino
                    pygame.key.stop_text_input()
                elif tecla == pygame.K_TAB:
                    foco = 1 - foco
                    cursor = len(nomes[foco])
                elif tecla == pygame.K_LEFT:
                    cursor = max(0, cursor - 1)
                elif tecla == pygame.K_RIGHT:
                    cursor = min(len(nomes[foco]), cursor + 1)
                elif tecla == pygame.K_HOME:
                    cursor = 0
                elif tecla == pygame.K_END:
                    cursor = len(nomes[foco])
                elif tecla == pygame.K_BACKSPACE and cursor > 0:
                    nomes[foco] = nomes[foco][:cursor - 1] + nomes[foco][cursor:]
                    cursor -= 1
                    aviso = ""
                elif tecla == pygame.K_DELETE:
                    nomes[foco] = nomes[foco][:cursor] + nomes[foco][cursor + 1:]
                    aviso = ""
                elif evento.type == pygame.TEXTINPUT:
                    insercao = "".join(letra for letra in evento.text if letra.isprintable())
                    insercao = insercao[:LIMITE_NOME - len(nomes[foco])]
                    nomes[foco] = nomes[foco][:cursor] + insercao + nomes[foco][cursor:]
                    cursor += len(insercao)
                    aviso = ""

            elif tela in ("ranking", "historico"):
                if tecla == pygame.K_ESCAPE or (clique and VOLTAR.collidepoint(evento.pos)):
                    tela, aviso = "menu", ""
                    pygame.key.start_text_input()
                elif tecla == pygame.K_LEFT or (clique and ANTERIOR.collidepoint(evento.pos)):
                    pagina = max(0, pagina - 1)
                elif tecla == pygame.K_RIGHT or (clique and PROXIMA.collidepoint(evento.pos)):
                    pagina = min(paginas - 1, pagina + 1)

            elif confirmar_desistencia:
                tratar_comando_partida(evento)
            elif clique and MENU_JOGO.collidepoint(evento.pos):
                if jogo_encerrado or confirmar_saida:
                    tela, aviso = "menu", ""
                    pygame.display.set_caption("Xadrez ULTIMATE")
                    pygame.key.start_text_input()
                else:
                    confirmar_saida = True
            elif clique and aviso_gravacao and REPETIR_GRAVACAO.collidepoint(evento.pos):
                salvar_resultado()
            elif confirmar_saida:
                if tecla == pygame.K_ESCAPE:
                    confirmar_saida = False
            else:
                tratar_comando_partida(evento)

        if tela == "menu":
            desenhar_menu(nomes, foco, cursor, aviso)
        elif tela == "partida":
            if not confirmar_saida:
                atualizar_animacao(dt)
            desenhar_partida(confirmar_saida)
        else:
            desenhar_listagem(tela, linhas, pagina, paginas, aviso)
        pygame.display.flip()


if __name__ == "__main__":
    executar()
